import{_ as a,c as i,o as t,ag as n}from"./chunks/framework.CB_NIqHd.js";const h=JSON.parse('{"title":"Python for Applied AI","description":"","frontmatter":{},"headers":[],"relativePath":"python-for-ai/index.md","filePath":"python-for-ai/index.md"}'),o={name:"python-for-ai/index.md"};function r(s,e,l,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="python-for-applied-ai" tabindex="-1">Python for Applied AI <a class="header-anchor" href="#python-for-applied-ai" aria-label="Permalink to “Python for Applied AI”">​</a></h1><p>Use Python as the companion implementation language for data preparation, model-service integration and evaluation. The primary path uses Python/uv/pytest, then Pydantic/FastAPI and one model SDK. Learn the underlying boundaries rather than several competing frameworks at once.</p><ol><li><p><a href="./setup-and-basics.html">Setup, Syntax, Collections and Functions</a> — a locked environment and tested deterministic document preparation.</p></li><li><p><a href="./typed-modules-and-errors.html">Typed Modules and Explicit Errors</a> — validated domain records, adapter protocols and distinct failure categories.</p></li><li><p><a href="./configuration-and-logging.html">Configuration, Safe Logs and pytest Fixtures</a> — validated startup settings, owned JSON output and isolated tests.</p></li><li><p><a href="./bounded-document-streams.html">Bounded Document Streams</a> — lazy NDJSON, strict byte/schema limits and explicit file ownership.</p></li><li><p><a href="./async-http.html">Async HTTP and Integration Boundaries</a> — reusable clients, bounded streams, deadlines and structured task ownership.</p></li><li><p><a href="./fastapi-boundaries.html">Pydantic and FastAPI Boundaries</a> — strict DTOs, safe errors, authenticated byte limits and app-owned lifespan.</p></li><li><p><a href="./document-processing.html">Document Extraction and Provenance</a> — bounded text/CSV extraction, traceable chunks and complex-format decisions.</p></li><li><p><a href="./deployment.html">Deployment and Recovery Boundaries</a> — a locked ASGI release, real process smoke test and supervised rollout decisions.</p></li><li><p><a href="./model-sdk.html">Typed Model SDK Boundary</a> — one provider adapter, strict structured outputs and offline SDK integration tests.</p></li><li><p><a href="./token-budgets.html">Tokens and Context Budgets</a> — actual-payload counting, output reserves and explicit overflow recovery.</p></li><li><p><a href="./model-foundations.html">Model Families, Training and Inference</a> — a tested learning/inference distinction and hosted/open-weight trade-offs.</p></li><li><p><a href="./attention-and-sampling.html">Attention and Probabilistic Generation</a> — a worked masked-attention calculation and sampling boundaries.</p></li><li><p><a href="./embeddings-and-similarity.html">Embeddings and Similarity</a> — compatible spaces, bounded cosine ranking and permissions before top-k.</p></li><li><p><a href="./retrieval-context.html">Verified Evidence and Citations</a> — current authorized spans, exact source references and explicit abstention.</p></li><li><p><a href="./retrieval-pipeline.html">Retrieval Pipeline and Context Assembly</a> — conservative query variants, bounded reranking and final-payload token admission.</p></li><li><p><a href="./prompting-and-modalities.html">Prompt Design, Modalities and Adaptation</a> — versioned text/image requests, evidence limitations and prompt/retrieval/training decisions.</p></li><li><p><a href="./model-streaming.html">Model Streaming and Deadlines</a> — typed SSE lifecycle, terminal-only decisions, cancellation and distinct idle/overall budgets.</p></li><li><p><a href="./model-work-budgets.html">Model Work Budgets</a> — bounded admission, local request pacing and explicit retry/defer policies.</p></li><li><p><a href="./history-and-workflows.html">History, Summaries and Checked Workflows</a> — bounded complete exchanges, lossy-summary review and revision-aware stage recovery.</p></li><li><p><a href="./tool-boundaries.html">Typed Tool Boundaries</a> — bounded arguments, exact dispatch, current permissions and safe projected results.</p></li><li><p><a href="./tool-workflow-state.html">Tool Workflow State</a> — fixed routes, bounded read retries and local SQLite revision persistence.</p></li><li><p><a href="./approved-writes.html">Approved Writes and Recovery</a> — exact-command approvals, local atomic idempotency and uncertain-outcome recovery.</p></li><li><p><a href="./graph-memory.html">Graph Framework and Scoped Memory</a> — one pinned LangGraph fixture, current principal isolation and coordination trade-offs.</p></li><li><p><a href="./workflow-diagnostics.html">Workflow Diagnostics</a> — bounded projected traces, distinct failure categories and tested state transitions.</p></li><li><p><a href="./evaluation-lab.html">Versioned Evaluation Lab</a> — task criteria, curated slice/label ledger and deterministic dataset checks.</p></li><li><p><a href="./evaluation-measurements.html">Evaluation Measurements</a> — versioned baselines, latency conventions, usage subsets and explicit unknown cost.</p></li><li><p><a href="./vector-storage-lifecycle.html">Vector Storage and Lifecycles</a> — persistent exact scan, current ACL/version checks and staged updates/deletion/reindexing.</p></li><li><p><a href="./retrieval-debugging.html">Retrieval Debugging and Regressions</a> — duplicates, freshness, stage diagnosis and failures becoming checked cases.</p></li><li><p><a href="./model-economics.html">Model Task Economics</a> — whole-task amplification, quality-gated routing and shared local reservations.</p></li><li><p><a href="./cache-and-batch.html">Caching and Batch Work</a> — versioned private cache identity, unordered result correlation and cost/latency decisions.</p></li><li><p><a href="./prompt-injection-boundaries.html">Prompt Injection Boundaries</a> — direct/indirect attacks, task-scoped reads and data-leakage containment.</p></li><li><p><a href="./source-and-output-security.html">Source and Output Security</a> — tenant-scoped read-only sources, reviewed revisions and safe display sinks.</p></li><li><p><a href="./provenance-and-oversight.html">Provenance and Oversight</a> — source-to-decision references, meaningful human approval and durable audit records.</p></li><li><p><a href="./provider-data-lifecycle.html">Provider Data Lifecycle</a> — minimal export, derivative retention/deletion and verified provider boundaries.</p></li><li><p><a href="./mcp-primitives.html">MCP Roles and Primitives</a> — a pinned official-SDK catalogue with tools, resources, prompts and actual in-memory checks.</p></li><li><p><a href="./mcp-connections.html">MCP Schemas and Connections</a> — discovery/capability/version boundaries and an executed stdio subprocess lifecycle.</p></li><li><p><a href="./mcp-security.html">MCP Security and Trust</a> — actual HTTP-middleware token/scope/record-policy checks, minimal projection and untrusted tool-content boundaries.</p></li><li><p><a href="./mcp-lifecycle.html">MCP Errors and Lifecycles</a> — actual failure/cancellation/cleanup checks and explicit modern/legacy protocol behavior.</p></li><li><p><a href="./operations-and-data.html">Operations, ETL and Streamlit</a> — release gates, atomic ingestion checkpoints and a tested internal review prototype.</p></li><li><p><a href="./graphs-and-adaptation.html">Graph data, orchestration and adaptation</a> — permission-aware traversal, framework recovery choices and optional fine-tuning/data-split concepts.</p></li></ol><p>Later applied-AI lessons expand tool workflows and evaluation. Reading or running the supplied examples does not establish independent practice completion.</p>',4)])])}const u=a(o,[["render",r]]);export{h as __pageData,u as default};
